def transform(grid):
    h, w = len(grid), len(grid[0])
    # diagonal colors are indexed by c-r; infer their repeating period from seeds.
    # Search periods consistent with every nonzero seed and choose shortest.
    seeds = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v:
                seeds[(c-r) % w] = v
    for p in range(1, w+1):
        cyc = {}
        consistent = True
        for k, v in seeds.items():
            q = k % p
            if q in cyc and cyc[q] != v:
                consistent = False
                break
            cyc[q] = v
        if consistent and len(cyc) == p:
            return [[cyc[(c-r) % p] for c in range(w)] for r in range(h)]
    return [row[:] for row in grid]
