def transform(grid):
    h, w = len(grid), len(grid[0])
    # Horizontal stripe examples: copy the last stripe into the blank first row.
    if all(len(set(row)) == 1 for row in grid) and all(v == 0 for v in grid[0]):
        out = [row[:] for row in grid]
        out[0] = grid[-1][:]
        return out
    # Otherwise the motif is a repeating diagonal color sequence indexed by c-r.
    seeds = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v:
                seeds[(c-r) % w] = v
    for p in range(1, w + 1):
        cycle = {}
        consistent = True
        for k, v in seeds.items():
            q = k % p
            if q in cycle and cycle[q] != v:
                consistent = False
                break
            cycle[q] = v
        if consistent and len(cycle) == p:
            return [[cycle[(c-r) % p] for c in range(w)] for r in range(h)]
    return [row[:] for row in grid]
